#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);

    int v[500];
    int present[501] = {0};

    for (int i = 0; i < n; i++) {
        scanf("%d", &v[i]);
        present[v[i]] = 1;
    }

    int ans = 1;

    for (int a = 1; a <= n; a++) {
        if (!present[a]) continue;

        for (int b = a + 1; b <= n; b++) {
            if (!present[b]) continue;

            int len = 0;
            int last = 0;

            for (int i = 0; i < n; i++) {
                int x = v[i];

                if (x == a || x == b) {
                    if (x != last) {
                        len++;
                        last = x;
                    }
                }
            }

            if (len > ans) ans = len;
        }
    }

    printf("%d\n", ans);

    return 0;
}
